#[inline]
pub unsafe fn xmlURIUnescapeString(
    mut str: *const c_char,
    mut len: c_int,
    mut target: *mut c_char,
) -> *mut c_char {
    if str.is_null() {
        return ::core::ptr::null_mut::<c_char>();
    }
    if len <= 0 as c_int {
        len = strlen(str) as c_int;
    }
    if len < 0 as c_int {
        return ::core::ptr::null_mut::<c_char>();
    }

    let ret: *mut c_char = if target.is_null() {
        let p = xmlMallocAtomic.expect("non-null function pointer")((len + 1 as c_int) as size_t)
            as *mut c_char;
        if p.is_null() {
            xmlURIErrMemory(b"unescaping URI value\n\0" as *const u8 as *const c_char);
            return ::core::ptr::null_mut::<c_char>();
        }
        p
    } else {
        target
    };

    #[inline(always)]
    fn hex_val(b: u8) -> i32 {
        if b.wrapping_sub(b'0') <= 9 {
            (b - b'0') as i32
        } else {
            let lo = b | 0x20;
            if lo.wrapping_sub(b'a') <= 5 {
                (lo - b'a' + 10) as i32
            } else {
                -1
            }
        }
    }

    let mut remaining = len as isize;
    let mut in_p = str as *const u8;
    let mut out_p = ret as *mut u8;

    while remaining > 0 {
        // SAFETY: `in_p` points into the caller-provided input buffer and `remaining > 0`
        // guarantees the current byte is readable.
        let b0 = unsafe { *in_p };
        if b0 == b'%' && remaining > 2 {
            // SAFETY: `remaining > 2` guarantees the next two bytes are readable.
            let b1 = unsafe { *in_p.add(1) };
            // SAFETY: `remaining > 2` guarantees the next two bytes are readable.
            let b2 = unsafe { *in_p.add(2) };
            let h1 = hex_val(b1);
            if h1 >= 0 {
                let h2 = hex_val(b2);
                if h2 >= 0 {
                    // SAFETY: `out_p` points into the allocated/provided target buffer, which
                    // has space for at least `len + 1` bytes; we write exactly one output byte here.
                    unsafe { *out_p = ((h1 << 4) | h2) as u8 };
                    // SAFETY: advancing within the validated input/output ranges.
                    in_p = unsafe { in_p.add(3) };
                    // SAFETY: advancing within the validated input/output ranges.
                    out_p = unsafe { out_p.add(1) };
                    remaining -= 3;
                    continue;
                }
            }
        }

        // SAFETY: `remaining > 0` guarantees one readable input byte, and output capacity
        // is sufficient for one written byte.
        unsafe { *out_p = b0 };
        // SAFETY: advancing within the validated input/output ranges.
        in_p = unsafe { in_p.add(1) };
        // SAFETY: advancing within the validated input/output ranges.
        out_p = unsafe { out_p.add(1) };
        remaining -= 1;
    }

    // SAFETY: the output buffer was allocated/provided with room for the terminating NUL.
    unsafe { *out_p = 0 };
    ret
}

